<style>
/* GeoSync Operations — dashboard corporativo para logística */
:root { --primary:#2463a5; --primary-hover:#174a80; --bg:#eef3f8; --card:#fff; --sidebar:#0a1f38; --text-main:#132c47; --text-muted:#6b7d90; --border:#dbe4ed; --input-bg:#f8fafc; --radius-lg:12px; --radius-md:8px; --shadow-sm:0 1px 3px rgba(12,32,56,.08); --shadow-md:0 10px 28px rgba(12,32,56,.08); }
body { background:var(--bg); }
.sidebar { width:272px; padding:22px 14px; background:linear-gradient(180deg,#0d2b4d 0%,#071a30 100%); box-shadow:8px 0 28px rgba(4,18,34,.14); }
.logo { margin:0 10px 22px; padding-bottom:20px; border-bottom:1px solid rgba(255,255,255,.12); font-size:1.42rem; letter-spacing:.02em; }
.logo img { width:39px; height:39px; object-fit:contain; }
.user-card { margin:0 5px 20px; padding:12px; background:rgba(255,255,255,.08); border:1px solid rgba(255,255,255,.11); border-radius:10px; }
.user-card img { border:2px solid #62a4e8; }.user-info small { color:#a9bed5; }
.collapse-btn { width:calc(100% - 10px); margin:0 5px 14px; padding:9px; border:1px solid rgba(255,255,255,.12); border-radius:8px; background:rgba(255,255,255,.06); }
.menu-title { margin:15px 10px 6px; padding:0; color:#7e9bb9; font-size:.66rem; letter-spacing:.12em; }
.nav-link { margin:3px 3px; padding:11px 13px; border-radius:8px; color:#b9c9da; font-size:.88rem; }
.nav-link i { color:#83a7cd; }.nav-link:hover { background:rgba(255,255,255,.075); color:#fff; transform:none; }.nav-link.active { background:#2463a5; color:#fff; border-left:0; box-shadow:0 6px 16px rgba(0,0,0,.16); }.nav-link.active i { color:#fff; }
.sidebar-footer { padding-top:13px; border-top:1px solid rgba(255,255,255,.1); }.sidebar-status { background:rgba(32,181,122,.13); color:#6ee7b7; border-radius:8px; font-size:.75rem; }.logout-link { color:#fca5a5; }.logout-link:hover { background:rgba(239,68,68,.14); color:#fecaca; }
.main-content { margin-left:272px; padding:28px 36px 48px; background:var(--bg); }.workspace-bar { min-height:66px; display:flex; justify-content:space-between; align-items:center; margin-bottom:28px; padding:0 0 20px; border-bottom:1px solid #d7e1eb; }.workspace-kicker { margin:0 0 4px; color:#2463a5; font-size:.7rem; font-weight:800; letter-spacing:.12em; text-transform:uppercase; }.workspace-title { margin:0; color:#132c47; font-size:1.3rem; font-weight:800; }.workspace-status { display:flex; align-items:center; gap:9px; color:#3f5873; font-size:.8rem; font-weight:700; }.workspace-status::before { content:''; width:9px; height:9px; border-radius:99px; background:#20b57a; box-shadow:0 0 0 4px rgba(32,181,122,.13); }
.page > h1 { font-size:1.85rem; color:#132c47; letter-spacing:-.035em; margin-bottom:22px!important; }.stats-grid { gap:16px; margin-bottom:20px; }.stat-card { position:relative; overflow:hidden; min-height:120px; padding:20px; border:1px solid var(--border); border-radius:12px; box-shadow:var(--shadow-sm); }.stat-card::before { content:''; position:absolute; top:0; left:0; width:4px; height:100%; background:#2e90fa; }.stat-card:nth-child(2)::before{background:#20b57a}.stat-card:nth-child(3)::before{background:#f79009}.stat-card:nth-child(4)::before{background:#ef5350}.stat-card h4{color:var(--text-muted);font-size:.7rem;letter-spacing:.08em}.stat-card h2{font-size:2rem;color:#132c47}.stat-card>i{padding:11px;border-radius:10px;background:#edf5ff;font-size:1.2rem}
.content-card { padding:22px; border:1px solid var(--border); border-radius:12px; box-shadow:var(--shadow-sm); }.content-card h2,.content-card h3{color:#132c47;letter-spacing:-.02em}.charts-grid{gap:16px}.table-res{border:1px solid #e5ebf1;border-radius:9px}th{background:#f6f9fc;color:#64748b;font-size:.68rem;letter-spacing:.07em}td{color:#40566e;border-bottom-color:#e7edf3}table tr:hover td{background:#f6faff}.badge{border-radius:999px;padding:6px 10px;font-size:.7rem}.btn-salvar,.btn-acao{border-radius:8px;box-shadow:none}.map-container,#mapaAdmin,#mapaCliente,#mapaBox{border:1px solid var(--border);border-radius:10px;overflow:hidden}
body.dark-mode .main-content{background:#0d1a2a}body.dark-mode .workspace-title,body.dark-mode .page>h1,body.dark-mode .content-card h2,body.dark-mode .content-card h3,body.dark-mode .stat-card h2{color:#eff6ff}body.dark-mode .content-card,body.dark-mode .stat-card{border-color:#29415e;background:#142840}
@media(max-width:768px){.sidebar{left:-272px;width:272px!important}.sidebar-open .sidebar{left:0}.main-content,body.sidebar-collapsed .main-content{margin-left:0;padding:20px 16px 36px}.workspace-bar{margin-bottom:20px}.workspace-status{display:none}.stats-grid,.charts-grid{grid-template-columns:1fr!important}}
</style>
